    // C++ program to answer queries
// for N-th prime factor of a number
// Using Sieve of Eratosthenes method
#include <bits/stdc++.h>
using namespace std;

// Check if the number if prime or not
bool isPrime(int n)
{
    if (n <= 1) {
        return false;
    }
    for (int i = 2; i * i <= n; i++) {
        if (n % i == 0) {
            return false;
        }
    }
    return true;
}

// Function to find all the possible prime factors
vector<int> AllPrimeFactors(int N)
{
    vector<int> v;
    for (int i = 2; i * i <= N; i++) {
        while (N % i == 0) {
            v.push_back(i);
            N = N / i;
            if (isPrime(N)) {
                v.push_back(N);
                N = N / N;
            }
        }
    }
    return v;
}

// Function that returns answer
// for every query
int query(int n, int k)
{
    vector<int> ans = AllPrimeFactors(n);
    if (isPrime(n) && k == 1) {
        return n;
    }
    if (ans.size() < k) {
        return -1;
    }
    return ans[k - 1];
}

